helpers:
def _plain(value):
    """Dates, timestamps and decimals as strings, so locked results are plain literals; lists and rows recurse."""
    if hasattr(value, "isoformat"):
        return value.isoformat(sep=" ") if hasattr(value, "hour") else value.isoformat()
    if type(value).__name__ == "Decimal":
        return str(value)
    if isinstance(value, (list, tuple)):
        return [_plain(v) for v in value]
    if isinstance(value, dict):
        return {k: _plain(v) for k, v in value.items()}
    return value


def rows_on(query, **views):
    """Run query with the named temp views temporarily replaced by `SELECT ...` definitions; return rows as tuples."""
    saved = {name: spark.table(name) for name in views}
    try:
        for name, select in views.items():
            spark.sql(f"CREATE OR REPLACE TEMP VIEW {name} AS {select}")
        return [tuple(_plain(v) for v in row) for row in spark.sql(query).collect()]
    finally:
        for name, frame in saved.items():
            frame.createOrReplaceTempView(name)
